import { memo, useMemo } from "react";
import { Streamdown } from "streamdown";
import { createCodePlugin } from "@streamdown/code";
import { getToolStatus, areToolPropsEqual } from "../utils/format-tool";
import type { McpToolInfo } from "./tool-registry";
import { ToolRowBase } from "./tool-row-base";

export type McpToolProps = {
  part: any;
  mcpInfo: McpToolInfo;
  chatStatus?: string;
  defaultOpen?: boolean;
};

const PRIORITY_ARGS = [
  "query",
  "question",
  "email",
  "name",
  "id",
  "customer",
  "url",
  "issue",
  "body",
  "summary",
  "title",
];

const ACTIVE_VERBS: Record<string, string> = {
  List: "Listing",
  Get: "Getting",
  Create: "Creating",
  Update: "Updating",
  Delete: "Deleting",
  Search: "Searching",
  Fetch: "Fetching",
  Retrieve: "Retrieving",
  Send: "Sending",
  Generate: "Generating",
  Add: "Adding",
  Remove: "Removing",
  Modify: "Modifying",
  Draft: "Drafting",
  Manage: "Managing",
  Query: "Querying",
  Start: "Starting",
  Set: "Setting",
  Check: "Checking",
  Find: "Finding",
};

const COMPLETED_VERBS: Record<string, string> = {
  List: "Listed",
  Get: "Got",
  Create: "Created",
  Update: "Updated",
  Delete: "Deleted",
  Search: "Searched",
  Fetch: "Fetched",
  Retrieve: "Retrieved",
  Send: "Sent",
  Generate: "Generated",
  Add: "Added",
  Remove: "Removed",
  Modify: "Modified",
  Draft: "Drafted",
  Manage: "Managed",
  Query: "Queried",
  Start: "Started",
  Set: "Set",
  Check: "Checked",
  Find: "Found",
};

function getActiveTitle(info: McpToolInfo): string {
  const words = info.displayName.split(" ");
  const verb = words[0];
  const rest = words.slice(1).join(" ");
  const active = ACTIVE_VERBS[verb];
  if (active) return rest ? `${active} ${rest}` : active;
  return info.displayName;
}

function getCompletedTitle(info: McpToolInfo): string {
  const words = info.displayName.split(" ");
  const verb = words[0];
  const rest = words.slice(1).join(" ");
  const completed = COMPLETED_VERBS[verb];
  return completed
    ? rest
      ? `${completed} ${rest}`
      : completed
    : info.displayName;
}

function formatMcpArgs(input: any): string {
  if (!input || typeof input !== "object") return "";
  const entries = Object.entries(input).filter(
    ([, v]) => v !== undefined && v !== null && v !== "",
  );
  if (entries.length === 0) return "";

  const sorted = [...entries].sort(([a], [b]) => {
    const ai = PRIORITY_ARGS.indexOf(a);
    const bi = PRIORITY_ARGS.indexOf(b);
    if (ai !== -1 && bi !== -1) return ai - bi;
    if (ai !== -1) return -1;
    if (bi !== -1) return 1;
    return 0;
  });

  const parts: string[] = [];
  for (const [key, value] of sorted) {
    if (parts.length >= 2) break;
    const val = typeof value === "string" ? value : JSON.stringify(value);
    const display = val.length > 30 ? val.slice(0, 27) + "..." : val;
    parts.push(`${key}: ${display}`);
  }
  return parts.join("  ");
}

export function unwrapMcpOutput(output: any): any {
  if (!output) return output;
  if (Array.isArray(output)) {
    const textParts: string[] = [];
    for (const block of output) {
      if (block?.type === "text" && typeof block?.text === "string") {
        textParts.push(block.text);
      }
    }
    if (textParts.length > 0) {
      const combined = textParts.join("");
      try {
        return JSON.parse(combined);
      } catch {
        return combined;
      }
    }
    return output;
  }
  if (output?.type === "text" && typeof output?.text === "string") {
    try {
      return JSON.parse(output.text);
    } catch {
      return output.text;
    }
  }
  if (typeof output === "string") {
    try {
      return JSON.parse(output);
    } catch {
      return output;
    }
  }
  return output;
}

function formatOutputForDisplay(output: any): string {
  const unwrapped = unwrapMcpOutput(output);
  if (typeof unwrapped === "string") {
    return unwrapped.length > 3000
      ? unwrapped.slice(0, 3000) + "\n..."
      : unwrapped;
  }
  const text = JSON.stringify(unwrapped, null, 2);
  return text.length > 3000 ? text.slice(0, 3000) + "\n..." : text;
}

const code = createCodePlugin({
  themes: ["github-light", "github-dark"],
});

export const McpTool = memo(function McpTool({
  part,
  mcpInfo,
  chatStatus,
  defaultOpen,
}: McpToolProps) {
  const { isPending, isInterrupted } = getToolStatus(part, chatStatus);

  const title = useMemo(() => {
    if (part.state === "input-streaming")
      return `Preparing ${mcpInfo.displayName}`;
    if (isPending) return getActiveTitle(mcpInfo);
    return getCompletedTitle(mcpInfo);
  }, [part.state, isPending, mcpInfo]);

  const subtitle = useMemo(() => {
    if (part.state === "input-streaming") return "";
    return formatMcpArgs(part.input);
  }, [part.input, part.state]);

  const displayOutput = useMemo(() => {
    if (!part.output) return null;
    return formatOutputForDisplay(part.output);
  }, [part.output]);

  const codeBlock = useMemo(() => {
    if (!displayOutput) return null;
    const trimmed = displayOutput.trim();
    if (!trimmed) return null;
    const language =
      trimmed.startsWith("{") || trimmed.startsWith("[") ? "json" : "text";
    return `\`\`\`${language}\n${displayOutput}\n\`\`\``;
  }, [displayOutput]);

  const hasExpandableContent = !!codeBlock && !isPending;

  if (isInterrupted && !part.output) {
    return (
      <span className="text-sm text-an-tool-color-muted">
        {mcpInfo.displayName} interrupted
      </span>
    );
  }

  return (
    <div className="an-tool-mcp">
      <ToolRowBase
        shimmerLabel={title}
        completeLabel={title}
        isAnimating={isPending}
        detail={subtitle || undefined}
        trailingContent={undefined}
        expandable={hasExpandableContent}
        defaultOpen={defaultOpen}
      >
        {codeBlock && (
          <div className="an-markdown text-[12px]">
            <Streamdown plugins={{ code }} controls={{ code: false }}>
              {codeBlock}
            </Streamdown>
          </div>
        )}
      </ToolRowBase>
    </div>
  );
}, areToolPropsEqual);

/**
 * Tool state cache for detecting AI SDK in-place mutations.
 * AI SDK mutates objects in-place during streaming, so we must
 * cache state externally and compare cached values.
 */

type CachedToolState = {
  state: string | undefined;
  inputJson: string;
  outputJson: string;
};

const toolStateCache = new Map<string, CachedToolState>();

function getToolStateSnapshot(part: any): CachedToolState {
  return {
    state: part.state,
    inputJson: JSON.stringify(part.input || {}),
    outputJson: JSON.stringify(part.output || {}),
  };
}

function hasToolStateChanged(toolCallId: string, part: any): boolean {
  const cached = toolStateCache.get(toolCallId);
  const current = getToolStateSnapshot(part);

  if (!cached) {
    toolStateCache.set(toolCallId, current);
    return true;
  }

  const changed =
    cached.state !== current.state ||
    cached.inputJson !== current.inputJson ||
    cached.outputJson !== current.outputJson;

  if (changed) {
    toolStateCache.set(toolCallId, current);
  }

  return changed;
}

function arePartsEqual(prev: any, next: any): boolean {
  if (prev.toolCallId !== next.toolCallId) return false;
  if (prev.type !== next.type) return false;

  const toolCallId = next.toolCallId;
  if (!toolCallId) {
    return prev.state === next.state;
  }

  const changed = hasToolStateChanged(toolCallId, next);
  return !changed;
}

function isToolCompleted(part: any): boolean {
  if (part.output !== undefined && part.output !== null) return true;
  if (part.state === "error") return true;
  if (part.state === "result") return true;
  return false;
}

/** Deep compare function for tool part props. Used with React.memo(). */
export function areToolPropsEqual(
  prevProps: { part: any; chatStatus?: string },
  nextProps: { part: any; chatStatus?: string },
): boolean {
  const partsEqual = arePartsEqual(prevProps.part, nextProps.part);
  if (!partsEqual) return false;
  if (isToolCompleted(nextProps.part)) return true;
  if (prevProps.chatStatus !== nextProps.chatStatus) return false;
  return true;
}

/** Get tool status from part state */
export function getToolStatus(part: any, chatStatus?: string) {
  const basePending =
    part.state !== "output-available" && part.state !== "output-error";
  const isError =
    part.state === "output-error" ||
    (part.state === "output-available" && part.output?.success === false);
  const isSuccess = part.state === "output-available" && !isError;
  const isPending = basePending && chatStatus === "streaming";
  const isInterrupted =
    basePending && chatStatus !== "streaming" && chatStatus !== undefined;

  return { isPending, isError, isSuccess, isInterrupted };
}

import type React from "react";
import {
  IconSearch as Search,
  IconEye as Eye,
  IconFolderSearch as FolderSearch,
  IconGitBranch as GitBranch,
  IconTerminal2 as Terminal,
  IconCircleX as XCircle,
  IconFileCode as FileCode2,
  IconSparkles as Sparkles,
  IconGlobe as Globe,
  IconFilePlus as FilePlus,
  IconChecklist as ListTodo,
  IconLogout as LogOut,
} from "@tabler/icons-react";

export type ToolVariant = "simple" | "collapsible";

export type ToolMeta = {
  icon: React.ComponentType<{ className?: string }>;
  title: (part: any) => string;
  subtitle?: (part: any) => string;
  variant: ToolVariant;
};

function getDisplayPath(filePath: string): string {
  if (!filePath) return "";
  const prefixes = [
    "/project/sandbox/repo/",
    "/project/sandbox/",
    "/project/",
    "/workspace/",
  ];
  for (const prefix of prefixes) {
    if (filePath.startsWith(prefix)) return filePath.slice(prefix.length);
  }
  const worktreeMatch = filePath.match(
    /\.21st\/worktrees\/[^/]+\/[^/]+\/(.+)$/,
  );
  if (worktreeMatch) return worktreeMatch[1]!;
  if (filePath.startsWith("/")) {
    const parts = filePath.split("/");
    const rootIndicators = ["apps", "packages", "src", "lib", "components"];
    const rootIndex = parts.findIndex((p) => rootIndicators.includes(p));
    if (rootIndex > 0) return parts.slice(rootIndex).join("/");
  }
  return filePath;
}

function calculateDiffStats(oldString: string, newString: string) {
  const oldLines = oldString.split("\n");
  const newLines = newString.split("\n");
  const maxLines = Math.max(oldLines.length, newLines.length);
  let addedLines = 0;
  let removedLines = 0;
  for (let i = 0; i < maxLines; i++) {
    if (oldLines[i] !== undefined && newLines[i] !== undefined) {
      if (oldLines[i] !== newLines[i]) {
        removedLines++;
        addedLines++;
      }
    } else if (oldLines[i] !== undefined) {
      removedLines++;
    } else if (newLines[i] !== undefined) {
      addedLines++;
    }
  }
  return { addedLines, removedLines };
}

export const toolRegistry: Record<string, ToolMeta> = {
  "tool-Task": {
    icon: Sparkles,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      const subagentType = part.input?.subagent_type || "Agent";
      return isPending
        ? `Running ${subagentType}`
        : `${subagentType} completed`;
    },
    subtitle: (part) => {
      const desc = part.input?.description || "";
      return desc.length > 50 ? desc.slice(0, 47) + "..." : desc;
    },
    variant: "simple",
  },
  // Agent tool — renamed from "Task" in claude-agent-sdk 0.2.63+
  "tool-Agent": {
    icon: Sparkles,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      const subagentType = part.input?.subagent_type || "Agent";
      return isPending
        ? `Running ${subagentType}`
        : `${subagentType} completed`;
    },
    subtitle: (part) => {
      const desc = part.input?.description || "";
      return desc.length > 50 ? desc.slice(0, 47) + "..." : desc;
    },
    variant: "simple",
  },
  "tool-Skill": {
    icon: Sparkles,
    title: () => "Skill",
    subtitle: (part) => part.input?.skill || "",
    variant: "simple",
  },
  "tool-Grep": {
    icon: Search,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      if (isPending) return "Grepping";
      const numFiles = part.output?.numFiles || 0;
      return numFiles > 0 ? `Grepped ${numFiles} files` : "No matches";
    },
    subtitle: (part) => {
      const pattern = part.input?.pattern || "";
      const path = part.input?.path || "";
      if (path) {
        const combined = `${pattern} in ${getDisplayPath(path)}`;
        return combined.length > 40 ? combined.slice(0, 37) + "..." : combined;
      }
      return pattern.length > 40 ? pattern.slice(0, 37) + "..." : pattern;
    },
    variant: "simple",
  },
  "tool-Glob": {
    icon: FolderSearch,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      if (isPending) return "Exploring files";
      const numFiles = part.output?.numFiles || 0;
      return numFiles > 0 ? `Found ${numFiles} files` : "No files found";
    },
    subtitle: (part) => {
      const pattern = part.input?.pattern || "";
      return pattern.length > 40 ? pattern.slice(0, 37) + "..." : pattern;
    },
    variant: "simple",
  },
  "tool-Read": {
    icon: Eye,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Reading" : "Read";
    },
    subtitle: (part) => {
      const filePath = part.input?.file_path || "";
      if (!filePath) return "";
      return filePath.split("/").pop() || "";
    },
    variant: "simple",
  },
  "tool-Edit": {
    icon: FileCode2,
    title: (part) => {
      const filePath = part.input?.file_path || "";
      if (!filePath) return "Edit";
      return filePath.split("/").pop() || "Edit";
    },
    subtitle: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      if (isPending) return "";
      const oldString = part.input?.old_string || "";
      const newString = part.input?.new_string || "";
      if (!oldString && !newString) return "";
      if (oldString !== newString) {
        const { addedLines, removedLines } = calculateDiffStats(
          oldString,
          newString,
        );
        return `+${addedLines} -${removedLines}`;
      }
      return "";
    },
    variant: "simple",
  },
  "tool-Write": {
    icon: FilePlus,
    title: () => "Create",
    subtitle: (part) => {
      const filePath = part.input?.file_path || "";
      if (!filePath) return "";
      return filePath.split("/").pop() || "";
    },
    variant: "simple",
  },
  "tool-Bash": {
    icon: Terminal,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Running command" : "Ran command";
    },
    subtitle: (part) => {
      const command = part.input?.command || "";
      if (!command) return "";
      let normalized = command.replace(/\\\s*\n\s*/g, " ").trim();
      normalized = normalized.replace(
        /\/(?:Users|home|root)\/[^\s"']+/g,
        (match: string) => getDisplayPath(match),
      );
      return normalized.length > 50
        ? normalized.slice(0, 47) + "..."
        : normalized;
    },
    variant: "simple",
  },
  "tool-WebFetch": {
    icon: Globe,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Fetching" : "Fetched";
    },
    subtitle: (part) => {
      const url = part.input?.url || "";
      try {
        return new URL(url).hostname.replace("www.", "");
      } catch {
        return url.slice(0, 30);
      }
    },
    variant: "simple",
  },
  "tool-WebSearch": {
    icon: Search,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Searching web" : "Searched web";
    },
    subtitle: (part) => {
      const query = part.input?.query || "";
      return query.length > 40 ? query.slice(0, 37) + "..." : query;
    },
    variant: "collapsible",
  },
  "tool-TodoWrite": {
    icon: ListTodo,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      const action = part.input?.action || "update";
      if (isPending) return action === "add" ? "Adding todo" : "Updating todos";
      return action === "add" ? "Added todo" : "Updated todos";
    },
    subtitle: (part) => {
      const todos = part.input?.todos || [];
      if (todos.length === 0) return "";
      return `${todos.length} ${todos.length === 1 ? "item" : "items"}`;
    },
    variant: "simple",
  },
  "tool-PlanWrite": {
    icon: Sparkles,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      const action = part.input?.action || "create";
      if (isPending) {
        if (action === "create") return "Creating plan";
        if (action === "approve") return "Approving plan";
        return "Updating plan";
      }
      const status = part.input?.plan?.status;
      if (status === "awaiting_approval") return "Plan ready for review";
      if (status === "approved") return "Plan approved";
      if (status === "completed") return "Plan completed";
      return action === "create" ? "Created plan" : "Updated plan";
    },
    variant: "simple",
  },
  "tool-ExitPlanMode": {
    icon: LogOut,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Finishing plan" : "Plan complete";
    },
    variant: "simple",
  },
  "tool-NotebookEdit": {
    icon: FileCode2,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Editing notebook" : "Edited notebook";
    },
    subtitle: (part) => {
      const filePath = part.input?.file_path || "";
      if (!filePath) return "";
      return filePath.split("/").pop() || "";
    },
    variant: "simple",
  },
  "tool-BashOutput": {
    icon: Terminal,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Getting output" : "Command output";
    },
    subtitle: (part) => {
      const output = part.output;
      if (typeof output === "string" && output.trim()) return output.trim();
      const command = part.input?.command || "";
      if (!command) return "";
      let normalized = command.replace(/\\\s*\n\s*/g, " ").trim();
      normalized = normalized.replace(
        /\/(?:Users|home|root)\/[^\s"']+/g,
        (match: string) => getDisplayPath(match),
      );
      return normalized.length > 50
        ? normalized.slice(0, 47) + "..."
        : normalized;
    },
    variant: "simple",
  },
  "tool-KillShell": {
    icon: XCircle,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Stopping shell" : "Shell stopped";
    },
    subtitle: (part) => {
      const pid = part.input?.pid;
      return typeof pid === "number" ? `pid ${pid}` : "";
    },
    variant: "simple",
  },
  "tool-cloning": {
    icon: GitBranch,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Cloning repo" : "Repo cloned";
    },
    subtitle: (part) => part.input?.repo ?? "",
    variant: "simple",
  },
  "tool-Thinking": {
    icon: Sparkles,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Thinking..." : "Thought";
    },
    variant: "collapsible",
  },
};

// MCP tool parsing
const MCP_TOOL_PREFIX = "tool-mcp__";

export type McpToolInfo = {
  serverName: string;
  toolName: string;
  displayName: string;
  category: string;
};

const BUILTIN_MCP_TOOLS: Record<string, McpToolInfo> = {
  "tool-ListMcpResources": {
    serverName: "mcp",
    toolName: "list_resources",
    displayName: "List Resources",
    category: "list",
  },
  "tool-ListMcpResourcesTool": {
    serverName: "mcp",
    toolName: "list_resources",
    displayName: "List Resources",
    category: "list",
  },
  "tool-ReadMcpResource": {
    serverName: "mcp",
    toolName: "read_resource",
    displayName: "Read Resource",
    category: "get",
  },
  "tool-ReadMcpResourceTool": {
    serverName: "mcp",
    toolName: "read_resource",
    displayName: "Read Resource",
    category: "get",
  },
};

export function parseMcpToolType(partType: string): McpToolInfo | null {
  const builtin = BUILTIN_MCP_TOOLS[partType];
  if (builtin) return builtin;
  if (!partType.startsWith(MCP_TOOL_PREFIX)) return null;
  const withoutPrefix = partType.slice(MCP_TOOL_PREFIX.length);
  const separatorIndex = withoutPrefix.indexOf("__");
  if (separatorIndex === -1) return null;
  const serverName = withoutPrefix.slice(0, separatorIndex);
  const toolName = withoutPrefix.slice(separatorIndex + 2);
  return {
    serverName,
    toolName,
    displayName: toolName
      .replace(/_/g, " ")
      .replace(/\b\w/g, (c) => c.toUpperCase())
      .trim(),
    category: "other",
  };
}

import type { ReactNode } from "react";
import { Collapsible } from "@base-ui/react/collapsible";
import { TextShimmer } from "../text-shimmer";
import { IconChevronRight } from "@tabler/icons-react";
import { cn } from "../utils/cn";

export type ToolRowBaseProps = {
  icon?: ReactNode;
  shimmerLabel?: string;
  completeLabel: string;
  isAnimating: boolean;
  detail?: string;
  trailingContent?: ReactNode;
  expandable?: boolean;
  expanded?: boolean;
  defaultOpen?: boolean;
  onToggleExpand?: () => void;
  children?: ReactNode;
};

export function ToolRowBase({
  icon,
  shimmerLabel,
  completeLabel,
  isAnimating,
  detail,
  trailingContent,
  expandable = false,
  expanded,
  defaultOpen = false,
  onToggleExpand,
  children,
}: ToolRowBaseProps) {
  const isComplete = !isAnimating;
  const isExpanded = expanded ?? false;
  const canToggle = expandable && (isComplete || isExpanded || isAnimating);

  const row = (
    <div
      className={cn(
        "flex items-center max-w-full select-none gap-1 rounded-an-tool-border-radius",
        canToggle ? "cursor-pointer" : "cursor-default",
      )}
    >
      <div className="flex items-center gap-2 min-w-0 text-sm text-muted-foreground">
        {icon && (
          <span className="flex items-center justify-center size-3 shrink-0">
            {icon}
          </span>
        )}
        <span className="font-[450] whitespace-nowrap shrink-0">
          {isAnimating && shimmerLabel ? (
            <TextShimmer
              as="span"
              duration={1.2}
              className="inline-flex items-center leading-none h-4 m-0"
            >
              {shimmerLabel}
            </TextShimmer>
          ) : (
            completeLabel
          )}
        </span>
        {detail && (
          <span className="font-normal truncate min-w-0 flex-1 text-an-foreground-muted/60">
            {detail}
          </span>
        )}
        {trailingContent}
      </div>
      {expandable && (isComplete || isExpanded || isAnimating) && (
        <div>
          <IconChevronRight
            className={cn(
              "shrink-0 text-muted-foreground transition-transform duration-150 ease-out",
              "size-3",
              "rotate-0 group-data-panel-open:rotate-90",
            )}
          />
        </div>
      )}
    </div>
  );

  if (!expandable) {
    return <div className="flex flex-col gap-1">{row}</div>;
  }

  const rootProps =
    expanded === undefined
      ? { defaultOpen }
      : { open: expanded, onOpenChange: onToggleExpand };

  return (
    <Collapsible.Root className="flex flex-col gap-2 w-full" {...rootProps}>
      <Collapsible.Trigger
        className="group flex"
        disabled={!canToggle}
        aria-disabled={!canToggle}
      >
        {row}
      </Collapsible.Trigger>
      <Collapsible.Panel
        className={cn(
          "overflow-hidden",
          "h-[var(--collapsible-panel-height)] transition-all duration-150 ease-out",
          "data-ending-style:h-0 data-starting-style:h-0",
          "[&[hidden]:not([hidden='until-found'])]:hidden",
        )}
      >
        {children}
      </Collapsible.Panel>
    </Collapsible.Root>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Agent Elements tokens + utilities */

/*
 * AN Agent Chat - CSS Custom Properties
 * These are the default values. Override by redefining these vars in your app CSS.
 */
:root {
  /* Geometry — all radii derive from --an-border-radius */
  --an-border-radius: 16px;
  --an-message-border-radius: var(--an-border-radius);
  --an-input-border-radius: var(--an-border-radius);
  --an-tool-border-radius: 10px;
  --an-message-radius-inner-offset: 4px;
  --an-max-width: 420px;

  /* Colors - Light mode defaults */
  --an-background: #ffffff;
  --an-background-secondary: #f0f0f0;
  --an-background-tertiary: #f8f8f8;
  --an-foreground: #1a1a1a;
  --an-foreground-muted: #737373;
  --an-foreground-subtle: #a3a3a3;
  --an-border-color: #e4e4e7;
  --an-primary-color: #3b82f6;

  /* User Messages */
  --an-user-message-bg: #f5f5f5;
  --an-user-message-text: #1a1a1a;

  /* Input */
  --an-input-background: #ffffff;
  --an-input-border-color: #e4e4e7;
  --an-input-color: #1a1a1a;
  --an-input-placeholder-color: #a3a3a3;
  --an-input-focus-outline: transparent;
  --an-context-padding: 10px;

  /* Send/Stop Buttons */
  --an-send-button-bg: #3b82f6;
  --an-send-button-color: #ffffff;

  /* Tools */
  --an-tool-background: #f5f5f5;
  --an-tool-border-color: #e4e4e7;
  --an-tool-color: #1a1a1a;
  --an-tool-color-muted: #737373;

  /* Code */
  --an-code-background: #1e1e1e;
  --an-code-color: #d4d4d4;

  /* Diff colors */
  --an-diff-added-bg: rgba(34, 197, 94, 0.1);
  --an-diff-added-border: rgba(34, 197, 94, 0.5);
  --an-diff-added-text: #15803d;
  --an-diff-removed-bg: rgba(239, 68, 68, 0.1);
  --an-diff-removed-border: rgba(239, 68, 68, 0.5);
  --an-diff-removed-text: #dc2626;
}

/* Dark mode defaults */
.dark {
  --an-background: #0a0a0a;
  --an-background-secondary: #242424;
  --an-background-tertiary: #141414;
  --an-foreground: #fafafa;
  --an-foreground-muted: #8c8c8c;
  --an-foreground-subtle: #71717a;
  --an-border-color: #2a2a2a;
  --an-primary-color: #60a5fa;

  --an-user-message-bg: #1a1a1a;
  --an-user-message-text: #fafafa;

  --an-input-background: #0a0a0a;
  --an-input-border-color: #2a2a2a;
  --an-input-color: #fafafa;
  --an-input-placeholder-color: #71717a;
  --an-input-focus-outline: transparent;
  --an-context-padding: 12px;

  --an-send-button-bg: #60a5fa;
  /* Dark mode uses a lighter primary (#60a5fa) — pair it with black text so
     labels like "Approve" / send-arrow have proper contrast instead of
     low-contrast white-on-light-blue. */
  --an-send-button-color: #0a0a0a;

  --an-tool-background: #141414;
  --an-tool-border-color: #2a2a2a;
  --an-tool-color: #fafafa;
  --an-tool-color-muted: #8c8c8c;

  --an-code-background: #0a0a0a;
  --an-code-color: #d4d4d4;

  --an-diff-added-bg: rgba(34, 197, 94, 0.15);
  --an-diff-added-border: rgba(34, 197, 94, 0.4);
  --an-diff-added-text: #4ade80;
  --an-diff-removed-bg: rgba(239, 68, 68, 0.15);
  --an-diff-removed-border: rgba(239, 68, 68, 0.4);
  --an-diff-removed-text: #f87171;
}

@theme inline {
  --color-an-background: var(--an-background);
  --color-an-background-secondary: var(--an-background-secondary);
  --color-an-background-tertiary: var(--an-background-tertiary);
  --color-an-foreground: var(--an-foreground);
  --color-an-foreground-muted: var(--an-foreground-muted);
  --color-an-foreground-subtle: var(--an-foreground-subtle);
  --color-an-border-color: var(--an-border-color);
  --color-an-primary-color: var(--an-primary-color);
  --color-an-user-message-bg: var(--an-user-message-bg);
  --color-an-user-message-text: var(--an-user-message-text);
  --color-an-input-background: var(--an-input-background);
  --color-an-input-border-color: var(--an-input-border-color);
  --color-an-input-color: var(--an-input-color);
  --color-an-input-placeholder-color: var(--an-input-placeholder-color);
  --color-an-input-focus-outline: var(--an-input-focus-outline);
  --color-an-send-button-bg: var(--an-send-button-bg);
  --color-an-send-button-color: var(--an-send-button-color);
  --color-an-tool-background: var(--an-tool-background);
  --color-an-tool-border-color: var(--an-tool-border-color);
  --color-an-tool-color: var(--an-tool-color);
  --color-an-tool-color-muted: var(--an-tool-color-muted);
  --color-an-code-background: var(--an-code-background);
  --color-an-code-color: var(--an-code-color);
  --color-an-diff-added-bg: var(--an-diff-added-bg);
  --color-an-diff-added-border: var(--an-diff-added-border);
  --color-an-diff-added-text: var(--an-diff-added-text);
  --color-an-diff-removed-bg: var(--an-diff-removed-bg);
  --color-an-diff-removed-border: var(--an-diff-removed-border);
  --color-an-diff-removed-text: var(--an-diff-removed-text);
  --radius-an-message: var(--an-message-border-radius);
  --radius-an-message-inner: calc(
    var(--an-message-border-radius) - var(--an-message-radius-inner-offset)
  );
  --radius-an-input-border-radius: var(--an-input-border-radius);
  --radius-an-tool-border-radius: var(--an-tool-border-radius);
  --spacing-an-context-padding: var(--an-context-padding);
  --max-width-an: var(--an-max-width);
  --spacing-an-user-message-x: 14px;
  --spacing-an-user-message-y: 10px;
}

/* TextShimmer animation */
@keyframes an-shimmer {
  from {
    background-position: 100% center;
  }
  to {
    background-position: 0% center;
  }
}

@keyframes an-blink {
  50% {
    opacity: 0;
  }
}

@keyframes loading-dots {
  0%,
  100% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
}

@keyframes an-ellipsis {
  0% {
    width: 0;
  }
  33% {
    width: 0.33em;
  }
  66% {
    width: 0.66em;
  }
  100% {
    width: 1em;
  }
}

.an-text-shimmer {
  display: inline-block;
  background-size: 250% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  background-image: linear-gradient(
    90deg,
    var(--an-foreground-subtle, #a3a3a3) 0%,
    var(--an-foreground-subtle, #a3a3a3) 40%,
    var(--an-foreground-muted, #737373) 50%,
    var(--an-foreground-subtle, #a3a3a3) 60%,
    var(--an-foreground-subtle, #a3a3a3) 100%
  );
  background-repeat: no-repeat;
}

.an-text-shimmer--active {
  animation: an-shimmer var(--an-shimmer-duration, 2s) linear infinite;
}

.an-ellipsis {
  display: inline-block;
  overflow: hidden;
  width: 0;
  vertical-align: bottom;
  animation: an-ellipsis 1.2s steps(1, end) infinite;
}

.an-markdown pre code {
  counter-reset: none !important;
}

.an-markdown pre code > span::before {
  content: none !important;
  display: none !important;
}

.an-markdown pre code > span {
  padding-left: 0 !important;
}

/* Diff */
.an-edit-diff,
.an-edit-diff pre,
.an-edit-diff code {
  font-size: 12px;
}

.dark .an-edit-tool-card {
  background-color: #000;
}

[data-theme="dark"] .an-edit-tool-card {
  background-color: #000;
}

.dark .an-edit-tool-card .an-edit-diff,
.dark .an-edit-tool-card .an-edit-diff pre,
.dark .an-edit-tool-card .an-edit-diff code {
  background-color: #000 !important;
}

[data-theme="dark"] .an-edit-tool-card .an-edit-diff,
[data-theme="dark"] .an-edit-tool-card .an-edit-diff pre,
[data-theme="dark"] .an-edit-tool-card .an-edit-diff code {
  background-color: #000 !important;
}

/* Markdown Code Block */
.an-markdown [data-streamdown="code-block"] {
  padding: 0;
  border: 1px solid var(--an-border-color);
  border-radius: var(--an-tool-border-radius);
  background: transparent;
  gap: 0;
}

.an-markdown [data-streamdown="code-block-header"] {
  padding: 0px 10px 0px 8px;
  height: auto;
  font-size: 12px;
  height: 28px;
  background: transparent;
  border-bottom: 1px solid var(--color-an-tool-border-color);
  background-color: var(--an-tool-background);
  position: relative;
}

.an-markdown div:has(> [data-streamdown="code-block-actions"]) {
  position: absolute;
  height: auto;
  margin: 0;
  top: 0;
  right: 0;
  height: 28px;
  padding-right: 8px;
}

.an-markdown [data-streamdown="code-block-actions"] {
  background: transparent;
  border: none;
  backdrop-filter: none;
  padding: 0;
}

.an-markdown [data-streamdown="code-block-actions"] button > svg {
  width: 14px;
  height: 14px;
}

.an-markdown [data-streamdown="code-block-body"] {
  margin: 0;
  padding-top: 8px;
  padding-bottom: 8px;
  background: transparent;
  border: transparent;
  overflow-x: auto;
}

.an-markdown [data-streamdown="code-block"] pre,
.an-markdown [data-streamdown="code-block"] code {
  font-size: 12px;
  background: transparent;
}
